        "<strong>Dictionary (Easton's).</strong> <strong>ADONIBEZEK</strong> Lord of Bezek, a Canaanitish king who, having subdued seventy of the chiefs that were around him, made an attack against the armies of Judah and Simeon, but was defeated and brought as a captive to Jerusalem, where his thumbs and great toes were cut off. He confessed that God had requited him for his like cruelty to the seventy kings whom he had subdued (Judges 1:4-7; comp. 1 Samuel 15:33).",
