    (
        1,
        35,
        "a",
        "",
        "dict-easton",
        "Dictionary",
        "Easton.",
        "<strong>Dictionary (Easton's).</strong> <strong>AJALON</strong> and Aij’alon, place of deer. (1.) A town and valley originally assigned to the tribe of Dan, from which, however, they could not drive the Amorites (Judges 1:35). It was one of the Levitical cities given to the Kohathites (1 Chronicles 6:69). It was not far from Beth-shemesh (2 Chronicles 28:18). It was the boundary between the kingdoms of Judah and Israel, and is frequently mentioned in Jewish history (2 Chronicles 11:10; 1 Samuel 14:31; 1 Chronicles 8:13). With reference to the valley named after the town, Joshua uttered the celebrated command, “Sun, stand thou still on Gibeon; and thou, Moon, in the valley of Ajalon” (Joshua 10:12). It has been identified as the modern Yalo, at the foot of the Beth-horon pass (q.v.). In the Tell Amarna letters Adoni-zedek (q.v.) speaks of the destruction of the “city of Ajalon” by the invaders, and describes himself as “afflicted, greatly afflicted” by the calamities that had come on the land, urging the king of Egypt to hasten to his help. (2.) A city in the tribe of Zebulun (Judges 12:12), the modern Jalun, three miles north of Cabul.",
        "Easton's Illustrated Bible Dictionary, M. G. Easton (1897). Public domain.",
    ),
    (
        1,
        35,
        "b",
        "",
        "dict-easton",
        "Dictionary",
        "Easton.",
        "<strong>Dictionary (Easton's).</strong> <strong>HERES</strong> sun. (1.) “Mount Heres” (Judges 1:35), Hebrews Har-heres, i.e., “sun-mountain;” probably identical with Irshemesh in Joshua 19:41. (2.) Isaiah 19:18, marg. (See ON.)",
        "Easton's Illustrated Bible Dictionary, M. G. Easton (1897). Public domain.",
    ),
