    # ---- ch 2 ----
    (
        2,
        10,
        "",
        "another generation arose after them who didn’t know Yahweh",
        "comm",
        "Note",
        "Note",
        "<strong>The Deuteronomistic thesis.</strong> The single sentence on which the entire book turns. The generation that knew Yahweh gives way to one that doesn’t — and what follows for the next twenty-one chapters is a long demonstration of what happens when covenant memory fails. The same loss-of-memory motif organizes much of the Deuteronomistic History (Joshua–2 Kings) and reappears in the Pentateuch’s warnings (Deut 8:11–18). The book of Judges is, structurally, a sustained meditation on this verse.",
        "User original",
    ),
