    (
        6,
        5,
        "b",
        "",
        "dict-easton",
        "Dictionary",
        "Easton.",
        "<strong>Dictionary (Easton's).</strong> <strong>GRASSHOPPER</strong> belongs to the class of neuropterous insects called Gryllidae. This insect is not unknown in Palestine. In Judges 6:5; 7:12; Job 39:30; Jeremiah 46:23, where the Authorized Version has “grasshopper,” the Revised Version more correctly renders the Hebrew word (‘arbeh) by “locust.” This is the case also in Amos 7:1; Nah. 3:17, where the Hebrew word gob is used; and in Leviticus 11:22; Numbers 13:33; Ecclesiastes 12:5; Isaiah 40:22, where hagab is used. In all these instances the proper rendering is probably “locust” (q.v.).",
        "Easton's Illustrated Bible Dictionary, M. G. Easton (1897). Public domain.",
    ),
