    (
        7,
        7,
        "",
        "I will save you by the three hundred men who lapped",
        "comm",
        "Note",
        "Note",
        "<strong>The three hundred.</strong> Yahweh reduces Gideon’s army from 32,000 to 300 — a deliberate inversion of the more-troops-equals-more-victory logic of ancient warfare. The criterion (lapping water versus kneeling) has invited centuries of speculation about which group was more vigilant; the text itself is opaque about why this method was chosen. The theological point is the inversion itself: deliverance is from God, not from numbers (Deut 20 articulated the same principle). The ratio (300 against 135,000 — see 8:10) makes the point unmissable.",
        "User original",
    ),
