    # ---- ch 11 ----
    (
        11,
        30,
        "",
        "Jephthah vowed a  vow to Yahweh",
        "comm",
        "Note",
        "Note",
        "<strong>Jephthah’s vow.</strong> The vow — “whoever comes out of the doors of my house to meet me… I will offer it as a burnt offering” (11:31) — is presented without authorial endorsement. Compare the Akedah (Gen 22), where God provides a ram in the thicket. Here no ram appears. Jewish and Christian interpreters have split between (a) literal sacrifice, (b) lifelong dedication to celibate temple service, and (c) the text as a critical exposure of a vow rashly made. The text’s own framing — Jephthah’s daughter mourning her virginity rather than her death (11:37–38) — has fueled the second reading; but the explicit “he did to her according to his vow” (11:39) reads more naturally as the first. Modern critical readings tend to take the narrative as a horrified portrait of what happens when Israelite practice slides toward Canaanite child-sacrifice norms — a failure that the book diagnoses without softening.",
        "User original",
    ),
