    # ---- ch 16 ----
    (
        16,
        30,
        "",
        "Let me die with the Philistines",
        "comm",
        "Note",
        "Note",
        "<strong>Samson’s death.</strong> The hero’s final prayer asks not for victory but for revenge (16:28); the text reports that he killed more in his death than in his life (16:30). Hebrews 11:32 lists Samson among the heroes of faith — a placement that has troubled Christian readers for centuries. The book of Judges itself avoids moralizing: Samson is a deliverer who saves nobody, who frees no territory, who dies destroying a temple full of unnamed Philistine civilians. He is the final major judge, and the trajectory from Othniel (3:9–11, simple and noble) to Samson (sprawling and morally chaotic) charts the book’s argument: the era of the judges is unsustainable.",
        "User original",
    ),
