    # ---- ch 17 ----
    (
        17,
        6,
        "",
        "In those days there was no king in Israel",
        "comm",
        "Note",
        "Note",
        "<strong>The refrain.</strong> This formula appears four times in the book’s last five chapters (17:6, 18:1, 19:1, 21:25), each time framing escalating chaos: idol-making, tribal civil war, the Levite’s concubine, the near-extinction of Benjamin. The book is making an argument the reader can’t miss — its closing frame primes for the books of Samuel, where the demand for a king becomes inevitable. Whether the refrain is pro-monarchic, anti-monarchic, or descriptive depends on the reader; but the editorial pattern is unmistakable.",
        "User original",
    ),
