        "Note",
        "Note",
        """<strong>The Song of Deborah.</strong> One of the oldest extant Hebrew poems (perhaps 12th c. BCE), and one of the few biblical texts attributed to a woman. Deborah’s self-designation as "a mother in Israel" combines maternal and judicial authority — she is both nurturer and warrior in the same leader. Judges 4 (the prose version) and Judges 5 (the poetic version) preserve a parallel double witness; the poem is generally older than the prose.""",
