        "Note",
        """<strong>Jephthah’s vow.</strong> One of the most ethically troubling stories in scripture. The narrative neither explicitly condemns nor endorses the vow’s fulfillment. Some Jewish and Christian interpreters argued that Jephthah’s daughter was dedicated to perpetual virginity rather than killed — but the Hebrew of v.39 most naturally reads as sacrifice. Hebrews 11:32 lists Jephthah among the heroes of faith without commenting on this episode.""",
