        "Note",
        "Note",
        "<strong>Samson’s death.</strong> The strongest of the judges ends his life by pulling down the temple of Dagon — killing thousands of Philistines and himself. Hebrews 11:32 lists Samson among the faithful; Augustine and others wrestled with whether his death qualifies as a permitted suicide. The narrative’s parallels to Christ have been noted since Origen: a Nazirite-like figure, betrayed by a kiss-of-treachery, dying with arms outstretched between two pillars, victorious in death.",
